```
#include <stdio.h>

#define SIZE 5

int main() {
    int list[SIZE] = {3, 2, 5, 1, 4};
    int temp;

    printf("정렬 전 순서\n");
    for (int i = 0; i < SIZE; i++)
        printf("%d ", list[i]);
    printf("\n");

    for (int i = 0; i < SIZE - 1; i++) { // SIZE - 1 -> 마지막 대상은 비교 필요X
        for (int j = i + 1; j < SIZE; j++) { // j = i + 1 -> 선정 위치 다음값부터 마지막까지 비교
            if (list[i] > list[j]) {
                temp = list[i];
                list[i] = list[j];
                list[j] = temp;
            }
        }
    }

    printf("정렬 후 순서\n");
    for (int i = 0; i < SIZE; i++)
        printf("%d ", list[i]);
    printf("\n");

    return 0;
}
