#include <stdio.h>

int count_num(int number) {
    static int count = 1; // 정적변수로 자릿수 세는거

    if (number / 10 != 0) { // 나머지 0 나올 때 까지 나눠줌
        count++;
        count_num(number / 10); // 정수값 나눠서 재귀
    }
    return count; // 나머지 0 나오면 자릿수 돌려보냄
